//! Row types for the design sheets; the rows themselves are generated by build.rs.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Slot {
    Skill,
    Ultimate,
}

#[derive(Clone, Copy, Debug)]
pub enum AudioPick {
    Index(usize),
    Random,
    Unset,
}

pub struct StatProfile {
    pub id: &'static str,
    pub hp_mult: f32,
    pub fp_mult: f32,
    pub stamina_mult: f32,
    pub damage_taken_mult: f32,
    pub ki_regen_per_s: f32,
    pub er_speffect: Option<i32>,
}

pub struct AudioRow {
    pub id: &'static str,
    pub bank: &'static str,
    pub pick: AudioPick,
    pub fighter: Option<&'static str>,
}

pub struct Ability {
    pub id: &'static str,
    pub name: &'static str,
    pub owner: &'static str,
    pub slot: Slot,
    pub delivery: Delivery,
    pub element: &'static str,
    pub dmg_mult: f32,
    pub fp_cost: i32,
    pub cooldown_s: f32,
    pub range_m: f32,
    pub charge: bool,
    pub er_anim: Option<i32>,
    pub er_bullet: i32,
    pub creator_pool: bool,
    /// wind-up before release (aura + voice)
    pub charge_s: f32,
    /// how it hits (shown in the fighter select)
    pub kind: Kind,
    /// hits on one enemy the damage is split over; 0 = estimated from the script
    pub hits: f32,
    /// a chain of hits: labeled COMBO in the fighter select and the HUD
    pub combo: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Melee,
    Aoe,
    Ranged,
}

impl Kind {
    pub fn label(self) -> &'static str {
        match self {
            Kind::Melee => "Melee",
            Kind::Aoe => "AOE",
            Kind::Ranged => "Ranged",
        }
    }
}

pub struct Fighter {
    pub id: &'static str,
    pub name: &'static str,
    pub series: &'static str,
    pub jf_dlc: bool,
    /// Ability ids; "$loadout" means the player's own pick (Your Tarnished).
    pub abilities: [&'static str; 4],
    pub awakening: Option<&'static str>,
    pub stat_profile: &'static str,
    /// audio row id for this fighter's JUMP FORCE voice bank
    pub voice: Option<&'static str>,
    /// armor ids [head, body, arms, legs] to look like; None = the player's own look
    pub outfit: Option<[i32; 4]>,
    /// per piece: colour its textures are recoloured to (a new model made on the player's PC)
    pub recolor: Option<[Option<[u8; 3]>; 4]>,
    /// per piece: fan-made model shipped in skins/<name>.bnd (replaces the recolour for that piece)
    pub skin: Option<[Option<&'static str>; 4]>,
    /// hair PartsId (body type A); None = keep the player's own
    pub hair_model: Option<u32>,
    /// hair/brow/beard colour; None = keep the player's own
    pub hair_rgb: Option<[u8; 3]>,
    /// skin colour; None = keep the player's own
    pub skin_rgb: Option<[u8; 3]>,
    /// build sliders [head, chest, abdomen, arms, legs]; None = keep the player's own
    pub body: Option<[u8; 5]>,
    /// model scale
    pub height: f32,
    /// SpEffect whose visuals are the fighter's aura
    pub aura_speffect: i32,
    /// 0.8.0: an extra defensive or movement ability ("unbreakable", "substitution", "full_cowl")
    pub passive: Option<&'static str>,
    /// fights with bare hands (weapon.rs); a weapon carried on the back and drawn for abilities
    pub bare_hands: bool,
    pub move_weapon: Option<u32>,
    /// the air dash is a Superman flight (movement.rs)
    pub flies: bool,
    /// the fighter's own particle effects (fx.rs)
    pub particles: Option<&'static str>,
}

/// The passive's name and what it does (fighter select).
pub fn passive_text(id: &str) -> (&'static str, &'static str) {
    match id {
        "unbreakable" => ("Symbol of Peace", "Can't be hurt while charging in with a skill"),
        "substitution" => ("Substitution Jutsu", "Once every 20 s, a heavy hit is swapped for a log: no damage"),
        "full_cowl" => ("Full Cowl", "A second double jump and a second air dash"),
        _ => ("", ""),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum When {
    InWorld,
    Grace,
    Menu,
}

pub struct InputRow {
    pub id: &'static str,
    pub keyboard: i32,
    /// XInput button mask; all bits must be held
    pub controller: u16,
    pub when: When,
}

/// One of Elden Force's own animations (sheet: anims): the cue it plays for (anim.rs).
pub struct AnimRow {
    pub id: u32,
    pub cue: &'static str,
    /// a strike that sword fighters keep as Elden Ring's weapon swing
    pub weapon_swing: bool,
}

include!(concat!(env!("OUT_DIR"), "/sheets.rs"));

pub fn input(id: &str) -> &'static InputRow {
    INPUTS.iter().find(|i| i.id == id).unwrap_or_else(|| panic!("inputs sheet has no row {id}"))
}

pub fn ability(id: &str) -> Option<&'static Ability> {
    ABILITIES.iter().find(|a| a.id == id)
}

pub fn fighter(id: &str) -> Option<&'static Fighter> {
    FIGHTERS.iter().find(|f| f.id == id)
}

pub fn profile(id: &str) -> &'static StatProfile {
    STAT_PROFILES.iter().find(|p| p.id == id).unwrap_or(&STAT_PROFILES[0])
}

pub fn audio(id: &str) -> Option<&'static AudioRow> {
    AUDIO.iter().find(|a| a.id == id)
}
